-- Kort #276 väg (a) (Bengt 1/10, DECISIONS #421): vad betyder "aktiv" för en oljehändelse i situation_archive? Arkivet ser aldrig
-- Trafikverkets radering (last_seen står stilla), så aktiv måste avgöras av start- och sluttid. Hur ofta saknas sluttiden, hur långa
-- är händelserna, och hur många vore aktiva nu under tre definitioner? Bara antal. Körs med dbknapp i läsläge.
SELECT count(*) AS alla, sum((end_time IS NULL)::int) AS utan_sluttid, sum((geom IS NULL)::int) AS utan_punkt, percentile_disc(0.5) WITHIN GROUP (ORDER BY end_time - start_time) AS median_langd, percentile_disc(0.9) WITHIN GROUP (ORDER BY end_time - start_time) AS p90_langd, max(end_time - start_time) AS langst FROM situation_archive WHERE message_type_value = 'NonWeatherRelatedRoadConditions'
SELECT sum((start_time <= now() AND (end_time IS NULL OR end_time > now()))::int) AS aktiva_sluttid_eller_ingen, sum((start_time <= now() AND end_time > now())::int) AS aktiva_med_sluttid, sum((start_time <= now() AND (end_time > now() OR (end_time IS NULL AND start_time > now() - interval '24 hours')))::int) AS aktiva_ingen_sluttid_max_24h FROM situation_archive WHERE message_type_value = 'NonWeatherRelatedRoadConditions' AND geom IS NOT NULL
SELECT date_trunc('day', start_time)::date AS dag, count(*) AS nya, sum((end_time IS NULL)::int) AS utan_sluttid, round(avg(extract(epoch FROM (end_time - start_time)) / 3600)::numeric, 1) AS timmar_snitt FROM situation_archive WHERE message_type_value = 'NonWeatherRelatedRoadConditions' AND start_time > now() - interval '10 days' GROUP BY 1 ORDER BY 1
